"""One shared, pinned installer for Loom's secure Aider distribution."""

from __future__ import annotations

AIDER_PATCHER_BASE64 = ""

AIDER_INSTALL_SCRIPT: str = f"""\
set -euo pipefail
umask 077

AIDER_VENV="${{LOOM_AIDER_VENV:-/opt/loom-agents/aider}}"
case "$AIDER_VENV" in
  /opt/loom-agents/aider|/opt/agent-runtimes/python-cli/aider) ;;
  *)
    echo "unsupported LOOM_AIDER_VENV" >&2
    exit 64
    ;;
esac

aider_venv_preflight() {{
  local current=""
  local component
  local metadata
  local owner
  local mode
  IFS='/' read -r -a components <<< "${{AIDER_VENV#/}}"
  for component in "${{components[@]}}"; do
    current="$current/$component"
    if [[ -L "$current" ]]; then
      echo "aider venv parent is unsafe" >&2
      return 1
    fi
    if [[ ! -e "$current" ]]; then
      break
    fi
    if [[ ! -d "$current" ]]; then
      echo "aider venv parent is unsafe" >&2
      return 1
    fi
    metadata="$(stat -c '%u:%a' -- "$current")" || {{
      echo "aider venv parent is unsafe" >&2
      return 1
    }}
    owner="${{metadata%%:*}}"
    mode="${{metadata#*:}}"
    if [[ "$owner" != "0" && "$owner" != "$(id -u)" ]] \
      || [[ $((8#$mode & 8#22)) -ne 0 ]]; then
      echo "aider venv parent is unsafe" >&2
      return 1
    fi
  done
}}

aider_venv_preflight

aider_venv_guard() {{
  AIDER_GUARD_EXPECTED_PARENT_ID="${{1:-}}" AIDER_VENV="$AIDER_VENV" python3 - <<'PY'
import os
import stat
import sys


_DIRECTORY_FLAGS = (
    os.O_RDONLY
    | os.O_DIRECTORY
    | getattr(os, "O_CLOEXEC", 0)
    | getattr(os, "O_NOFOLLOW", 0)
)
_EXPECTED_UID = os.geteuid()
_TARGET = os.environ["AIDER_VENV"]
_EXPECTED_PARENT_ID = os.environ["AIDER_GUARD_EXPECTED_PARENT_ID"]


def fail() -> None:
    print("aider venv parent is unsafe", file=sys.stderr)
    raise SystemExit(1)


def identity(metadata: os.stat_result) -> tuple[int, int]:
    return metadata.st_dev, metadata.st_ino


def safe_mode(metadata: os.stat_result) -> bool:
    return not metadata.st_mode & 0o022


def open_directory(name: str, parent_fd: int) -> tuple[int, os.stat_result]:
    try:
        before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if stat.S_ISLNK(before.st_mode) or not stat.S_ISDIR(before.st_mode):
            fail()
        descriptor = os.open(name, _DIRECTORY_FLAGS, dir_fd=parent_fd)
        opened = os.fstat(descriptor)
        after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except OSError:
        fail()
    if (
        not stat.S_ISDIR(opened.st_mode)
        or identity(before) != identity(opened)
        or identity(opened) != identity(after)
    ):
        os.close(descriptor)
        fail()
    return descriptor, opened


def trusted_for_creation(metadata: os.stat_result) -> bool:
    return metadata.st_uid == _EXPECTED_UID and safe_mode(metadata)


if not os.path.isabs(_TARGET) or os.path.normpath(_TARGET) != _TARGET:
    fail()
parts = _TARGET.split("/")[1:]
if not parts or parts[-1] != "aider":
    fail()
try:
    current_fd = os.open("/", _DIRECTORY_FLAGS)
except OSError:
    fail()
try:
    current_metadata = os.fstat(current_fd)
    if not stat.S_ISDIR(current_metadata.st_mode) or not safe_mode(current_metadata):
        fail()
    for component in parts[:-1]:
        try:
            os.stat(component, dir_fd=current_fd, follow_symlinks=False)
        except FileNotFoundError:
            if not trusted_for_creation(current_metadata):
                fail()
            try:
                os.mkdir(component, 0o700, dir_fd=current_fd)
            except OSError:
                fail()
            descriptor, metadata = open_directory(component, current_fd)
            if not trusted_for_creation(metadata):
                os.close(descriptor)
                fail()
            os.fsync(current_fd)
        except OSError:
            fail()
        else:
            descriptor, metadata = open_directory(component, current_fd)
            if not trusted_for_creation(metadata):
                os.close(descriptor)
                fail()
        os.close(current_fd)
        current_fd = descriptor
        current_metadata = metadata
    if not trusted_for_creation(current_metadata):
        fail()
    try:
        os.stat("aider", dir_fd=current_fd, follow_symlinks=False)
    except FileNotFoundError:
        pass
    except OSError:
        fail()
    else:
        venv_fd, venv_metadata = open_directory("aider", current_fd)
        try:
            if not trusted_for_creation(venv_metadata):
                fail()
        finally:
            os.close(venv_fd)
    parent_identity = str(current_metadata.st_dev) + ":" + str(current_metadata.st_ino)
    if _EXPECTED_PARENT_ID and _EXPECTED_PARENT_ID != parent_identity:
        fail()
    print(parent_identity)
finally:
    os.close(current_fd)
PY
}}

AIDER_WORK_DIR="$(TMPDIR=/tmp mktemp -d)"
trap 'rm -rf "$AIDER_WORK_DIR"' EXIT

if command -v apk >/dev/null 2>&1; then
  apk add --no-cache ca-certificates python3 py3-pip py3-virtualenv
elif command -v apt-get >/dev/null 2>&1; then
  export DEBIAN_FRONTEND=noninteractive
  apt-get update
  apt-get install -y --no-install-recommends ca-certificates python3 python3-pip python3-venv
  rm -rf /var/lib/apt/lists/*
else
  echo "no supported package manager (apk/apt-get); cannot install aider" >&2
  exit 1
fi

AIDER_TRUSTED_PARENT_ID="$(aider_venv_guard)"
AIDER_REVALIDATED_PARENT_ID="$(aider_venv_guard "$AIDER_TRUSTED_PARENT_ID")"
test "$AIDER_REVALIDATED_PARENT_ID" = "$AIDER_TRUSTED_PARENT_ID"
python3 -m venv --clear "$AIDER_VENV"
AIDER_PYTHON="$AIDER_VENV/bin/python"
AIDER_SOURCE_DIR="$AIDER_WORK_DIR/source"
AIDER_OUTPUT_DIR="$AIDER_WORK_DIR/patched"
AIDER_WHEELHOUSE="$AIDER_WORK_DIR/wheelhouse"
mkdir -p "$AIDER_SOURCE_DIR" "$AIDER_OUTPUT_DIR" "$AIDER_WHEELHOUSE"

"$AIDER_PYTHON" -m pip download \
  --disable-pip-version-check \
  --only-binary=:all: \
  --no-deps \
  --dest "$AIDER_SOURCE_DIR" \
  "aider-chat==0.86.2"
AIDER_SOURCE_WHEEL="$AIDER_SOURCE_DIR/aider_chat-0.86.2-py3-none-any.whl"
printf '%s  %s\\n' \
  "64f6a0c66c9f4633ad9f479bca3e64ebcba02b9da03c6b604b74a44736b2416e" \
  "$AIDER_SOURCE_WHEEL" | sha256sum -c -

AIDER_PATCHER="$AIDER_WORK_DIR/aider_distribution.py"
printf '%s' '{AIDER_PATCHER_BASE64}' | base64 -d > "$AIDER_PATCHER"
AIDER_PATCHED_WHEEL="$(
  "$AIDER_PYTHON" "$AIDER_PATCHER" \
    --source-wheel "$AIDER_SOURCE_WHEEL" \
    --output-directory "$AIDER_OUTPUT_DIR"
)"
test "$AIDER_PATCHED_WHEEL" = \
  "$AIDER_OUTPUT_DIR/aider_chat-0.86.2+loom.2-py3-none-any.whl"

"$AIDER_PYTHON" -m pip download \
  --disable-pip-version-check \
  --only-binary=:all: \
  --dest "$AIDER_WHEELHOUSE" \
  "$AIDER_PATCHED_WHEEL"
"$AIDER_PYTHON" -m pip install \
  --disable-pip-version-check \
  --no-index \
  --find-links "$AIDER_WHEELHOUSE" \
  "aider-chat==0.86.2+loom.2"

"$AIDER_PYTHON" -m pip check
"$AIDER_PYTHON" - <<'PY'
import importlib.metadata
import aider
import aider.coders
import aider.io
import aider.models

expected_requirements = (
    "aider-chat==0.86.2+loom.2",
    "litellm==1.84.1",
    "importlib-metadata==8.9.0",
    "gitpython==3.1.59",
)
for requirement in expected_requirements:
    distribution, version = requirement.split("==", 1)
    actual = importlib.metadata.version(distribution)
    if actual != version:
        raise SystemExit(f"{{distribution}}: expected {{version}}, got {{actual}}")
if aider.__version__ != "0.86.2":
    raise SystemExit(f"aider module: expected 0.86.2, got {{aider.__version__}}")

aider.models.Model("openai/gpt-4o-mini")
aider.io.InputOutput()
object.__new__(aider.coders.Coder)
PY
ln -sf "$AIDER_VENV/bin/aider" /usr/local/bin/aider
aider --version
aider --help | grep -F -- '--message' >/dev/null
"""
